/** 🎚️ The memory a machine can give to inferring projects: half of its memory, less when less is available now (less the floor the others keep), and never what the small first booking of the process that asks says: the inference itself is admitted by the capacity gate later (measured: a 16 GB worker asked with 2048 MB, had a grant of 0 MB per project and a wave of 0 projects, so every project was refused), and a project that outgrows its grant is stopped by the memory governor. Swap is neither added nor subtracted: the available memory of a Linux host is `MemAvailable`, which has no swap in it. */
export function fleetAdmittedMegabytesV1(input:Readonly<{hostMegabytes:number;availableMegabytes?:number}>,policy:WantedPolicyV1=wantedPolicyV1):number{
 const half=Math.floor(input.hostMegabytes/2);
 return input.availableMegabytes===undefined||!Number.isFinite(input.availableMegabytes)?half:Math.max(0,Math.min(half,Math.floor(input.availableMegabytes-policy.availableFloorMegabytes)));
}

